def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 4

    def bands(n, separator_indices):
        result = []
        start = 0
        for i in separator_indices:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    row_bands = bands(h, sep_rows)
    col_bands = bands(w, sep_cols)

    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    panels = []
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            count = sum(v != bg for row in panel for v in row)
            panels.append((r0, r1, c0, c1, panel, count))

    source = max(panels, key=lambda p: p[5])
    sr0, sr1, sc0, sc1, pattern, _ = source
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _, _ in panels:
        if (r1 - r0, c1 - c0) == (sr1 - sr0, sc1 - sc0):
            for i in range(r1 - r0):
                for j in range(c1 - c0):
                    out[r0 + i][c0 + j] = pattern[i][j]
    return out
